/* Public explanation scope only. Private source identities stay outside this repository. */
const notes={
 5:['snow','적설·융설','Snow processes','경사·D8 방향·시간대는 경험적 융설계수에 반영됩니다. 원자료의 일사·경사면 적설 유지 표현은 직접적인 일사 에너지수지나 눈 이동 계산을 뜻하지 않습니다.','Slope, D8 direction and time of day adjust an empirical melt factor. Radiation and slope-retention imagery in the original does not imply a direct energy-balance or snow-transport calculation.'],
 8:['hotstart','HotStart','HotStart','체크포인트에 포함되는 상태는 실행 경로별로 확인해야 합니다. 모든 수리 확장의 상태가 동일하게 복원되는 것은 아닙니다.','Check state coverage for the selected path; not every hydraulic extension is restored by the same checkpoint.'],
 10:['subcal','소유역 보정','Subbasin calibration','다지점 보고·진단과 목표지점 보정을 구분합니다. 모든 소유역의 매개변수를 동시에 자동 보정한다는 의미는 아닙니다.','Distinguish multi-site reporting and diagnostics from target-site calibration; this does not imply simultaneous automatic calibration of every subbasin.'],
 13:['multires','1D–2D·다중해상도','1D–2D and multi-resolution','실행 경로별 단방향·양방향 교환을 구분합니다. Patch는 원지형 해상도를 유지하고 배경을 묶는 방식이며, 입력보다 세밀한 지형정보를 생성하지 않습니다.','Distinguish one-way and two-way execution paths. Patches retain source-terrain resolution while background cells are grouped; no terrain detail beyond the input is created.'],
 16:['netcdf','결과·물수지','Outputs and water balance','파일별 격자·출력 시각이 다를 수 있습니다. 교환 물수지, 전체 유역 폐합, 관측 적합도는 별도 평가 항목입니다.','Meshes and output times may differ by file. Exchange balance, watershed closure and observational fit are separate assessments.'],
 17:['estuary','통합 범위','Integration scope','전체 통합 그림은 연구·개발 방향을 포함합니다. D층은 완전한 지하수유동 모형과 다르며, Estuary2DV는 별도 실험 모형입니다.','The integrated overview includes research and development directions. The D-layer is not a complete groundwater solver, and Estuary2DV is a separate experimental model.']
};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function cardNote(id,lang){const n=notes[id];if(!n)return '';const ko=lang==='ko';return `<p class="media-review-note"><strong>${ko?'현재 설명 보완':'Current clarification'}</strong> ${esc(n[ko?3:4])} <a href="${ko?'ko/':'./'}#cap-${n[0]}">${ko?'기능 설명':'Capability details'} →</a></p>`;}
function review(lang){const ko=lang==='ko';return `<section class="note content-review" data-language="${lang}" ${ko?'':'hidden'}><h2>${ko?'소개자료를 읽을 때 확인할 범위':'Scope notes for the introduction materials'}</h2><p>${ko?'2026-09-20 · 홈페이지 46개 기능의 설명·도식을 구현 경로와 공개 설명자료에 대조했습니다. 아래는 설명 범위의 보완이며 수치 정확도 검증이나 기능 등급 변경을 뜻하지 않습니다. 기존 PDF·영상·이미지는 원본으로 보존합니다.':'2026-09-20 · Descriptions and diagrams for all 46 website capabilities were reviewed against implementation paths and explanatory materials. These clarifications are not numerical validation or maturity upgrades. Original PDF, video and images are preserved.'}</p><details><summary>${ko?'6개 자료의 보완 내용 보기':'Read clarifications for six materials'}</summary>${Object.entries(notes).map(([id,n])=>`<h3>${esc(n[ko?1:2])}</h3>${cardNote(id,lang)}`).join('')}</details></section>`;}
module.exports={notes,cardNote,review};
